catalog_script_client.script:
function onLoad() {

  var style = document.createElement('style');
  style.innerHTML = `

    /* ── Page background ── */
    body,
    #sc_cat_item_guide,
    .catalog-home,
    div#cat_item_content,
    div.catalog-container,
    div.sc-content-container {
      background: #f0f7ff !important;
      background-image:
        radial-gradient(circle at 20% 20%, rgba(30,136,229,0.05) 0%, transparent 50%),
        radial-gradient(circle at 80% 80%, rgba(38,166,154,0.05) 0%, transparent 50%) !important;
    }

    /* ── Top accent strip ── */
    body::before {
      content: '' !important;
      display: block !important;
      height: 4px !important;
      width: 100% !important;
      background: linear-gradient(90deg, #1E88E5, #26A69A) !important;
      position: fixed !important;
      top: 0 !important;
      left: 0 !important;
      z-index: 9999 !important;
    }

    /* ── Form card ── */
    div.catalog-details {
      background: #ffffff !important;
      border-radius: 12px !important;
      border: 2px solid #1E88E5 !important;
      border-top: 4px solid #1E88E5 !important;
      padding: 24px !important;
      box-shadow: 0 4px 16px rgba(30,136,229,0.10) !important;
      max-width: 720px !important;
      margin: 0 auto !important;
    }

    /* ── Field labels ── */
    label.sc-variable-label,
    .catalog-field-label {
      font-weight: 600 !important;
      color: #2c3e50 !important;
      font-size: 13px !important;
    }

    /* ── Input fields ── */
    input[type=text], input[type=date], select, textarea {
      border: 1px solid #d0d7de !important;
      border-radius: 6px !important;
      padding: 7px 10px !important;
      font-size: 13px !important;
      background: #f8fafc !important;
      width: 96% !important;
    }

    /* ── Input focus ── */
    input[type=text]:focus, select:focus, textarea:focus {
      border-color: #1E88E5 !important;
      background: #fff !important;
      outline: none !important;
    }

    /* ── Submit button ── */
    #sc_submit,
    input[name=sysparm_ordered_item_checkout],
    .catalog-submit-button button,
    button[type=submit] {
      background: #1E88E5 !important;
      color: #fff !important;
      border: none !important;
      border-radius: 7px !important;
      padding: 10px 28px !important;
      font-size: 14px !important;
      font-weight: 600 !important;
      cursor: pointer !important;
    }

    /* ── Cancel button ── */
    #sc_cancel,
    .catalog-cancel-button,
    a.catalog-cancel {
      border: 1px solid #c8d0db !important;
      border-radius: 7px !important;
      padding: 9px 20px !important;
      font-size: 13px !important;
      color: #4a5568 !important;
      background: transparent !important;
      margin-left: 10px !important;
    }

  `;
  document.head.appendChild(style);

  /* ── Rename submit button ── */
  setTimeout(function() {
    var submitBtn = document.querySelector('#sc_submit')
                 || document.querySelector('input[name="sysparm_ordered_item_checkout"]')
                 || document.querySelector('.catalog-submit-button button')
                 || document.querySelector('button[type="submit"]');

    if (submitBtn) {
      submitBtn.value       = 'Submit — Create New Patient';
      submitBtn.textContent = 'Submit — Create New Patient';
      submitBtn.innerHTML   = 'Submit — Create New Patient';
    }
  }, 500);

}
